function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}
	var fieldName = 'rh_phone_contact';
	var phone = newValue.replace(/\D/g, '');
	var pattern = /^[1-9]{2}([2-8]|9[1-9])[0-9]{7}$/g;
	if(!pattern.test(phone)) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'Número de telefone inválido!', 'error');
	} else {
		var _phone;
		if (phone.length == 10) {
			_phone = phone.replace(/(\d{2})(\d{4})(\d{4})/, '($1) $2-$3');
		}
		else if (phone.length == 11) {
			_phone = phone.replace(/(\d{2})(\d{5})(\d{4})/, '($1) $2-$3');
		}
		g_form.hideFieldMsg(fieldName, true);
		g_form.setValue(fieldName, _phone);
	}
}

function onSubmit() {

   var operadora = g_form.getValue('v_nome_operadora_beneficiario');
    var motivo = g_form.getValue('v_motivo_atendimento_beneficiario');

	if ((operadora == '1' || operadora == '2' || operadora == '3' || operadora == '5') && motivo == '4') {
