function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    //Type appropriate comment here, and begin script below

    var idUser = g_form.getValue('rh_user_id_impacted');
    var motivo = g_form.getValue('rh_motivo_atendimento_nao_realizado');
    var oferta = g_form.getDisplayValue('service_offering');

    var block = new Date(2013, 1, 28);
    block.setHours(0, 0, 0);
    var admissao = new Date(g_form.getValue('rh_date_entry'));
    admissao.setDate((admissao.getDate() + 1));
    admissao.setHours(0, 0, 0);

    if (idUser == '') {
        g_form.setValue('service_offering', '');
        g_form.setValue('rh_qual_solicitacao', '');
        g_form.showFieldMsg('rh_user_id_impacted', 'Preencha a matrícula do impactado antes.', 'info');
        return;
    }

    if (oferta == 'Beneficiário(a) não consegue ser atendido(a)' && motivo == 'problemas_acessar_app' && admissao > block) {
        setTimeout(function() {
            g_form.setValue('block', 'true');
        }, 500);
        setTimeout(function() {
            g_form.setValue('block', 'false');
        }, 500);

    }

}

