function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}

	var fieldName = "rh_dependent_cpf";
	var cpf = newValue.replace(/[^\d]+/g, '');
	// Elimina CPFs invalidos conhecidos	
	if (cpf == '' || cpf.length != 11 ||(/0{11,}|1{11,}|2{11,}|3{11,}|4{11,}|5{11,}|6{11,}|8{11,}|9{11,}/g).test(cpf)) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}
	// Valida 1o digito	
	var add = 0;
	for (var i = 0; i < 9; i++) add += parseInt(cpf.charAt(i)) * (10 - i);
	var rev = 11 - (add % 11);
	if (rev == 10 || rev == 11) rev = 0;
	if (rev != parseInt(cpf.charAt(9))) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}
	// Valida 2o digito	
	add = 0;
	for (var k = 0; k < 10; k++) add += parseInt(cpf.charAt(k)) * (11 - k);
	rev = 11 - (add % 11);
	if (rev == 10 || rev == 11) rev = 0;
	if (rev != parseInt(cpf.charAt(10))) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}

	if(cpf === (g_form.getValue('rh_cpf_impacted')).replace(/[^\d]+/g, '')){
        g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF informado não pode ser igual ao CPF do impactado', 'error');
		return;
    }
    g_form.hideFieldMsg(fieldName, true);




	if(control == null) g_form.setValue(fieldName, formataCPF(cpf));
	else control.value = formataCPF(cpf);	

	function formataCPF(_cpf) {
		_cpf = _cpf.replace(/[^\d]/g, "");
		return _cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");
	}
}

function onSubmit() {
    //Type appropriate comment here, and begin script below

    var motivo = g_form.getValue('rh_motivo_atendimento_nao_realizado');
    var solicitacao = g_form.getValue('rh_qual_solicitacao');
    var operadora = g_form.getValue('rh_nome_operadora');
    //var cancelamento_obito = g_form.getValue('rh_cancelamento_obito');
    var oferta = g_form.getDisplayValue('service_offering');

    var block = new Date(2013, 1, 28);
    block.setHours(0, 0, 0);
    var admissao = new Date(g_form.getValue('rh_date_entry'));
    admissao.setDate((admissao.getDate() + 1));
    admissao.setHours(0, 0, 0);

    if (motivo == 'problemas_acessar_app' && operadora != 'outros') {
        g_form.addErrorMessage('<h3><b>Favor, entrar em contato com a operadora pelos canais informados</b></h3>');
        return false;
    }

    /*if (oferta == 'Solicitação de cancelamento de assistência médica' && (cancelamento_obito == 'No' || cancelamento_obito == 'Não')) {
        g_form.addErrorMessage('<h3><b>Atenção!</b><br>Para realizar o cancelamento da operadora <b>Unimed FESP</b> o(a) colaborador(a) deverá entrar em contato diretamente com a operadora através do telefone: <b>0800 772 3030</b></h3>');
        return false;
    }*/

    if (oferta == 'Solicitação de extensão de assistência médica' && (solicitacao == 'extensao_assistencia_medica' || solicitacao == 'formulario_solicitar_extensao_assistencia_medica') && admissao > block) {
        g_form.addErrorMessage('<h3><b>Atenção!</b><br>Somente colaboradores(as) admitidos até <b>28/02/2013</b>, que contribuiu com uma participação fixa mensal no seu plano de saúde, através do desconto em folha de pagamento, e <b>que tenha sido desligado por iniciativa da empresa, sem justa causa</b>, podem optar pela continuidade no plano.</h3>');
        return false;
    }

}

