function onChange(control, oldValue, newValue, isLoading) {
	if (isLoading || newValue == '') {
		return;
	}

	var fieldName = "rh_dependent_cpf";
	var cpf = newValue.replace(/[^\d]+/g, '');
	// Elimina CPFs invalidos conhecidos	
	if (cpf == '' || cpf.length != 11 ||(/0{11,}|1{11,}|2{11,}|3{11,}|4{11,}|5{11,}|6{11,}|8{11,}|9{11,}/g).test(cpf)) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}
	// Valida 1o digito	
	var add = 0;
	for (var i = 0; i < 9; i++) add += parseInt(cpf.charAt(i)) * (10 - i);
	var rev = 11 - (add % 11);
	if (rev == 10 || rev == 11) rev = 0;
	if (rev != parseInt(cpf.charAt(9))) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}
	// Valida 2o digito	
	add = 0;
	for (var k = 0; k < 10; k++) add += parseInt(cpf.charAt(k)) * (11 - k);
	rev = 11 - (add % 11);
	if (rev == 10 || rev == 11) rev = 0;
	if (rev != parseInt(cpf.charAt(10))) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}

	if(cpf === (g_form.getValue('rh_cpf_impacted')).replace(/[^\d]+/g, '')){
        g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF informado não pode ser igual ao CPF do impactado', 'error');
		return;
    }
    g_form.hideFieldMsg(fieldName, true);




	if(control == null) g_form.setValue(fieldName, formataCPF(cpf));
	else control.value = formataCPF(cpf);	

	function formataCPF(_cpf) {
		_cpf = _cpf.replace(/[^\d]/g, "");
		return _cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");
	}
}

