function onSubmit() {
    var offering = g_form.getValue('service_offering');

    if (offering === '94fb432887df221' + '0182a0d440cbb35ff') {
        var bairro = g_form.getValue('bairro');
        var estado = g_form.getValue('estado');
        var rua = g_form.getValue('rua');
        var municipio = g_form.getValue('municipio');
        var pais = g_form.getValue('pais');

        if (!bairro || !estado || !rua || !municipio || !pais) {
            var msg = "Por favor, preencha todos os campos obrigatórios:\n\n" +
                      "• Bairro\n" +
                      "• Estado\n" +
                      "• Endereço / Logradouro\n" +
                      "• Município\n" +
                      "• País";

            g_form.addInfoMessage(msg);
            return false;
        }
    }

    return true;
}

function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;

    if (!newValue) {
        // CEP apagado: limpa campos
        limparCamposEndereco();
        return;
    }

    // Antes de fazer a requisição, já limpamos os campos
    limparCamposEndereco();

    var ga = new GlideAjax('CepUtils');
    ga.addParam('sysparm_name', 'getEndereco');
    ga.addParam('sysparm_cep', newValue);

    ga.getXMLAnswer(function(answer) {
        var dados = JSON.parse(answer);

        if (!dados.erro) {
            g_form.setValue('rua', dados.rua);
            g_form.setValue('bairro', dados.bairro);
            g_form.setValue('municipio', dados.municipio);
            g_form.setValue('estado', dados.estado);
            g_form.setValue('pais', dados.pais);
            g_form.setValue('cep_valido', 'true');  // CEP válido
        } else {
            g_form.setValue('cep_valido', 'false');
            // Os campos já estão limpos e cep_valido está false
        }
    });

    // Função para limpar campos de endereço
    function limparCamposEndereco() {
        g_form.setValue('rua', '');
        g_form.setValue('bairro', '');
        g_form.setValue('municipio', '');
        g_form.setValue('estado', '');
        g_form.setValue('pais', '');
    }
}

