function onSubmit() {

	var impactadosArray = JSON.parse(g_form.getValue('csa_dados_do_impactado'));
	var impactadoUser = g_form.getValue('rh_user_id_impacted');
	var matriculaUser = impactadosArray[0].matricula;

var temDivergencia = false;
function validDiverg(impactadosArray, matriculaUser){
    for (var i = 0; i < impactadosArray.length; i++) {
        if(impactadosArray[i].matricula != matriculaUser){
            return true; 
        }
    }
    return false;
}

temDivergencia = validDiverg(impactadosArray, matriculaUser);

if(temDivergencia){
	g_form.setValue('rh_user_id_impacted', "");
	g_form.addErrorMessage("A solicitação só pode ser feita para um colaborador de cada vez.");
	return false;
} else {
	if(impactadoUser !== matriculaUser) {
		g_form.setValue('rh_user_id_impacted', "");
		g_form.addErrorMessage('A solicitação só pode ser feita para um colaborador de cada vez. Ajuste o campo Matrícula do impactado');
		return false;
	}
}
   return true;
}

