function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var fieldName = 'time_2'; 

    if (isLoading || isTemplate)
        return;


    if (!newValue) {
        g_form.hideFieldMsg(fieldName, true);
        return;
    }

    var timeStr = ('' + newValue).trim();

    // Valida formato HH:MM (24h)
    var match = timeStr.match(/^([01]\d|2[0-3]):([0-5]\d)$/);
    if (!match) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar um horário entre 9:00-12:00 ou 14:00-17:00.',
            'error',
            true
        );
        return;
    }

    var hour = parseInt(match[1], 10);
    var minute = parseInt(match[2], 10);
    var totalMinutes = hour * 60 + minute;

    // Faixas permitidas (inclusive):
    // 09:00–12:00 e 14:00–17:00
    var startMorning  = 9 * 60;   // 540
    var endMorning    = 12 * 60;  // 720
    var startAfternoon = 14 * 60; // 840
    var endAfternoon   = 17 * 60; // 1020

    var isInMorning   = (totalMinutes >= startMorning && totalMinutes <= endMorning);
    var isInAfternoon = (totalMinutes >= startAfternoon && totalMinutes <= endAfternoon);

    if (!isInMorning && !isInAfternoon) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar um horário entre 9:00-12:00 ou 14:00-17:00.',
            'error',
            true
        );
    } else {
        g_form.hideFieldMsg(fieldName, true);
    }
}

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var fieldName = 'date_2';

    if (isLoading || isTemplate)
        return;

    if (!newValue) {
        g_form.hideFieldMsg(fieldName, true);
        return;
    }

    var selectedDate = parsePortalDate(newValue);
    if (!selectedDate || isNaN(selectedDate.getTime())) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar uma data em até 3 dias úteis.',
            'error',
            true
        );
        return;
    }

    // Normaliza
    selectedDate.setHours(0, 0, 0, 0);

    var today = new Date();
    today.setHours(0, 0, 0, 0);

    var maxBusinessDate = calcMaxBusinessDate(today, 3);

    var dayOfWeek = selectedDate.getDay(); // 0 = domingo, 6 = sábado

    // Bloqueia sábado e domingo
    if (dayOfWeek === 0 || dayOfWeek === 6) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar uma data em até 3 dias úteis.',
            'error',
            true
        );
        return;
    }

    //  Bloqueia data anterior a hoje e > 3 dias úteis
    if (selectedDate < today || selectedDate > maxBusinessDate) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar uma data em até 3 dias úteis.',
            'error',
            true
        );
        return;
    }


    g_form.hideFieldMsg(fieldName, true);
}


function parsePortalDate(value) {
    if (!value)
        return null;

    var v = ('' + value).trim();
    var datePart = v.split(' ')[0];

    // Formato YYYY-MM-DD
    if (datePart.indexOf('-') > -1) {
        var p = datePart.split('-');
        if (p.length === 3 && p[0].length === 4)
            return new Date(parseInt(p[0],10), parseInt(p[1],10)-1, parseInt(p[2],10));
    }

    // Formato DD/MM/YYYY
    if (datePart.indexOf('/') > -1) {
        var p2 = datePart.split('/');
        if (p2.length === 3)
            return new Date(parseInt(p2[2],10), parseInt(p2[1],10)-1, parseInt(p2[0],10));
    }

    var d = new Date(v);
    return isNaN(d.getTime()) ? null : d;
}


  //Soma N dias úteis ignorando sáb e dom

function calcMaxBusinessDate(startDate, businessDays) {
    var date = new Date(startDate.getTime());
    var daysAdded = 0;

    while (daysAdded < businessDays) {
        date.setDate(date.getDate() + 1);
        var dow = date.getDay();
        if (dow !== 0 && dow !== 6) {
            daysAdded++;
        }
    }

    return date;
}

