    var hour = parseInt(match[1], 10);
    var minute = parseInt(match[2], 10);
    var totalMinutes = hour * 60 + minute;

    // Faixas permitidas (inclusive):
    // 09:00–12:00 e 14:00–17:00
    var startMorning  = 9 * 60;   // 540
    var endMorning    = 12 * 60;  // 720
    var startAfternoon = 14 * 60; // 840
    var endAfternoon   = 17 * 60; // 1020

    var isInMorning   = (totalMinutes >= startMorning && totalMinutes <= endMorning);
    var isInAfternoon = (totalMinutes >= startAfternoon && totalMinutes <= endAfternoon);

    if (!isInMorning && !isInAfternoon) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(
            fieldName,
            'Por favor, informar um horário entre 9:00-12:00 ou 14:00-17:00.',
            'error',
            true
        );
    } else {
        g_form.hideFieldMsg(fieldName, true);
    }
}

