	rev = 11 - (add % 11);
	if (rev == 10 || rev == 11) rev = 0;
	if (rev != parseInt(cpf.charAt(10))) {
		g_form.clearValue(fieldName);
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}

	g_form.hideFieldMsg(fieldName, true);

	if(control == null)  {

		if (g_form.getDisplayValue('service_offering') == 'Pré-análise de compatibilidade com a lei de cotas') {


			var ga = new GlideAjax('global.RHv2Ajax');
			ga.addParam('sysparm_name', 'getSolicCandidate');
			ga.addParam('sysparm_service_offering', g_form.getValue('service_offering'));
			ga.addParam('sysparm_cpf', g_form.getValue('rh_cpf_candidate'));
			ga.addParam('sysparm_user', g_form.getValue('rh_name_requester'));
			ga.getXMLAnswer(function (response) {

				var answer = JSON.parse(response);

				if (answer.ritm != '') {

					g_form.addErrorMessage('Encontramos na base chamado N° '+answer.ritm+' nessa unidade para o mesmo CPF');
					g_form.clearValue('rh_cpf_candidate');

					return false;
				}
			})	
		}

		g_form.setValue(fieldName, formataCPF(cpf));

	} 
	else  {
		control.value = formataCPF(cpf);
	}

	function formataCPF(_cpf) {
		_cpf = _cpf.replace(/[^\d]/g, "");
		return _cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");
	}
}

