function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    var fieldName = "rh_cnpj_union";

    var regexCNPJ = /^[A-Za-z0-9]{2}[\.]?[A-Za-z0-9]{3}[\.]?[A-Za-z0-9]{3}[\/]?[A-Za-z0-9]{4}[-]?[0-9]{2}$/;

    if (!regexCNPJ.test(newValue)) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(fieldName, 'CNPJ inválido!', 'error');
        return;
    }

    var tamanho, numeros, digitos, soma, pos, resultado;

    var cnpj = newValue.toString().replace(/[^A-Za-z0-9]+/g, '').toUpperCase();
    var hasLetter = /[A-Z]/.test(cnpj.substring(0, 12));

    if (!/^[A-Z0-9]{12}[0-9]{2}$/.test(cnpj)) {
        g_form.clearValue(fieldName);
        g_form.showFieldMsg(fieldName, 'CNPJ inválido!', 'error');
        return;
    }

    // Se tiver letras nas 12 primeiras posições, valida somente o formato
    if (!hasLetter) {
        if (cnpj === '' || cnpj.length !== 14 || (/0{14,}|1{14,}|2{14,}|3{14,}|4{14,}|5{14,}|6{14,}|7{14,}|8{14,}|9{14,}/g).test(cnpj)) {
            g_form.clearValue(fieldName);
            g_form.showFieldMsg(fieldName, 'CNPJ inválido!', 'error');
            return;
        }

        tamanho = cnpj.length - 2;
        numeros = cnpj.substring(0, tamanho);
        digitos = cnpj.substring(tamanho);
        soma = 0;
        pos = tamanho - 7;

        for (var i = tamanho; i >= 1; i--) {
            soma += numeros.charAt(tamanho - i) * pos--;
            if (pos < 2) pos = 9;
        }

        resultado = soma % 11 < 2 ? 0 : 11 - soma % 11;
        if (resultado != digitos.charAt(0)) {
            g_form.clearValue(fieldName);
            g_form.showFieldMsg(fieldName, 'CNPJ inválido!', 'error');
            return;
        }

        tamanho = tamanho + 1;
        numeros = cnpj.substring(0, tamanho);
        soma = 0;
        pos = tamanho - 7;

        for (i = tamanho; i >= 1; i--) {
            soma += numeros.charAt(tamanho - i) * pos--;
            if (pos < 2) pos = 9;
        }

        resultado = soma % 11 < 2 ? 0 : 11 - soma % 11;
        if (resultado != digitos.charAt(1)) {
            g_form.clearValue(fieldName);
            g_form.showFieldMsg(fieldName, 'CNPJ inválido!', 'error');
            return;
        }
    }

    g_form.hideFieldMsg(fieldName, true);

    if (control == null)
        g_form.setValue(fieldName, formataCNPJ(cnpj));
    else
        control.value = formataCNPJ(cnpj);
}

function formataCNPJ(_cnpj) {
    return _cnpj
        .toString()
        .replace(/[^A-Za-z0-9]/g, "")
        .toUpperCase()
        .replace(/^([A-Z0-9]{2})([A-Z0-9]{3})([A-Z0-9]{3})([A-Z0-9]{4})([0-9]{2})$/, "$1.$2.$3/$4-$5");
}

