				gaOculos.addParam('sysparm_impactado', impactado);
				gaOculos.addParam('sysparm_offering', offering);
				gaOculos.getXMLAnswer(function (response) {

					var answer = JSON.parse(response);

					setTimeout(function () {
						if (answer.exist == true) {
                     g_form.hideFieldMsg('service_offering');

							g_form.setValue('service_offering', '');
							g_form.addErrorMessage('Já existe uma solicitação para esta divergência, através do Case ' + answer.number + ', <a href="'+ answer.linkChamado +'" target="_blank">Clique aqui</a> para acessar o chamado.');

						} else {

							g_form.hideFieldMsg('service_offering');

						}
					}, 1000);

				});
			}
		});
	}
}

