        g_form.addErrorMessage('<b>Atenção:</b> Esta fila é exclusivamente destinada para alteração de e-mail na Wellhub (Gympass). Para solicitar a alteração do seu e-mail na TotalPass, por favor, entre em contato diretamente com a operadora através do SAC (telefone), pelo chat (APP) ou pelo e-mail: sac@totalpass.com.br ');

    }
    return retorno;
}

