function onChange(control, oldValue, newValue, isLoading) {
	var cpf = newValue.replace(/[^\d]+/g, '');
	if (isLoading || newValue == '' || oldValue.replace(/[^\d]+/g, '') == cpf) {
		return;
	}

	var fieldName = "candidate_cpf";

	fields.forEach(function(field) {
		g_form.setValue(field,"");
	});

	// Elimina CPFs / CNPJs invalidos conhecidos	
	if (cpf == '' || 
		(cpf.length != 11 && cpf.length != 14) ||
		cpf == "00000000000" ||
		cpf == "11111111111" ||
		cpf == "22222222222" ||
		cpf == "33333333333" ||
		cpf == "44444444444" ||
		cpf == "55555555555" ||
		cpf == "66666666666" ||
		cpf == "77777777777" ||
		cpf == "88888888888" ||
		cpf == "99999999999" || 
		(/0{14,}|1{14,}|2{14,}|3{14,}|4{14,}|5{14,}|6{14,}|7{14,}|8{14,}|9{14,}/g).test(cpf)) {
		g_form.setValue(fieldName,"");
		g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
		return;
	}

	if(cpf.length == 11) {
		// Valida 1o digito	
		var add = 0;
		for (var i = 0; i < 9; i++)
			add += parseInt(cpf.charAt(i)) * (10 - i);
		var rev = 11 - (add % 11);
		if (rev == 10 || rev == 11)
			rev = 0;
		if (rev != parseInt(cpf.charAt(9))) {
			g_form.setValue(fieldName,"");
			g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
			return;
		}
		// Valida 2o digito	
		add = 0;
		for (var k = 0; k < 10; k++)
			add += parseInt(cpf.charAt(k)) * (11 - k);
		rev = 11 - (add % 11);
		if (rev == 10 || rev == 11)
			rev = 0;
		if (rev != parseInt(cpf.charAt(10))) {
			g_form.setValue(fieldName,"");
			g_form.showFieldMsg(fieldName, 'CPF inválido!', 'error');
			return;
		}

	} 

	g_form.hideFieldMsg(fieldName, true);

	if (control == null) 
		g_form.setValue(fieldName, formatterIdentification(cpf));
	else 
		control.value = formatterIdentification(cpf);

}

function formatterIdentification(code) {
	if(code.length == 11)
		return code.replace(/[^\d]/g, "").replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4");

	return code.replace(/[^\d]/g, "").replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5");
}

